// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {
    ERC20PermitUpgradeable
} from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PermitUpgradeable.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IERC4626} from "./interfaces/IERC4626.sol";
import {IERC7535} from "./interfaces/IERC7535.sol";
import {IERC7540} from "./interfaces/IERC7540.sol";
import {ValidatorsRegistry} from "./ValidatorsRegistry.sol";
import {IStakePrecompile} from "./interfaces/IStakePrecompile.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

contract aprMON is
    ERC20Upgradeable,
    ERC20PermitUpgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    IERC4626,
    IERC7535,
    IERC7540
{
    using Math for uint256;

    struct RedeemData {

        uint256 shares;

        address controller;

        uint256 assets;

        bool claimed;

        uint256 timestamp;

        uint256 withdrawalBatchId;
    }

    struct UserRequests {

        uint256[] requestIds;

        uint256 emptyHead;
    }

    struct RequestData {

        uint256 id;

        bool claimed;

        bool claimable;

        uint256 shares;

        uint256 assets;

        uint256 timestamp;

        uint64 unlockEpoch;
    }

    struct OracleData {

        uint256 totalValidatorsStake;

        uint256 totalValidatorsScore;

        uint256 totalRewards;

        uint256 rebalanceUndelegated;

        uint256 deltaValidatorsStake;

        bool isDeltaPositive;

        uint256 lastBatch;
    }

    struct OracleParams {

        uint256 totalWithdrawalAmount;

        uint256 totalBurnableShares;

        uint256 nextRequestId;

        uint256 pendingDeposit;

        uint256 blockNumber;

        bool rebalanceNeeded;
    }

    enum OracleTxType {
        CLAIM_REWARDS,
        REBALANCE_DELEGATE,
        PROCESS_DEPOSITS_AND_WITHDRAWALS,
        REBALANCE_UNDELEGATE
    }

    uint256 internal constant MAX_BASIS_POINTS = 10000;

    uint256 internal constant MAX_PERCENTAGE = 100;

    uint256 public constant MIN_SHARE_SUPPLY = 1e12;

    uint256 public constant DUST_THRESHOLD = 1e9;

    address payable public stakePrecompile;

    address public oracleOperator;

    address public feeVault;

    uint256 public totalPendingDeposit;

    uint256 public burnableShares;

    uint256 public totalStaked;

    uint256 public lastProcessedRequestId;

    uint256 public rewardFeesAccumulated;

    uint256 public withdrawalFeesAccumulated;

    uint256 public nextRequestId;

    uint256 public lastProcessedBlockNumber;

    uint256 public minimumRedeem;

    uint256 public withdrawalFee;

    uint8 public rewardFee;

    mapping(uint256 => RedeemData) internal redeemRequests;

    mapping(address controller => mapping(address operator => bool)) public isOperator;

    address public validatorsRegistry;

    mapping(address => UserRequests) internal userRequests;

    mapping(address => mapping(uint256 => bool)) internal isEmptyRequestSlot;

    uint256 public epochLength;

    uint64 public withdrawalDelay;

    uint256 public latestUpdateBlockNumber;

    uint256 public rewardsDistributing;

    uint256 public currentWithdrawalBatchId;

    uint256 public lastProcessedWithdrawalBatchId;

    mapping(uint256 => uint64) public withdrawalBatchUnlockEpochs;

    mapping(uint256 => mapping(uint64 => uint8)) internal precompilePendingWithdrawalIds;

    uint256 public rebalanceBatchId;

    uint256 public rebalanceInProgress;

    bool public rebalanceBatchWithdrawn;

    OracleData internal oracleData;

    mapping(uint256 => ValidatorsRegistry.Validator[]) internal validatorBatches;

    mapping(uint64 => uint256) internal validatorStakes;

    uint256 public midUpdateAdjustment;

    mapping(OracleTxType => mapping(uint256 => bool)) public oracleUpdateTracking;

    uint256[] public validatorBatchIndices;

    OracleParams public oracleParams;

    event OracleDataUpdate(
        uint256 blockNumber,
        uint256 totalPendingDeposit,
        uint256 totalStaked,
        uint256 burnableShares,
        uint256 lastProcessedRequestId,
        uint256 rewardFeesAccumulated
    );

    event EpochRewardsUpdated(uint256 blockNumber, uint256 rewardsDistributing);

    event OracleOperatorUpdated(address oracle);

    event StakePrecompileUpdated(address stakePrecompile);

    event ValidatorsRegistryUpdated(address validatorsRegistry);

    event EpochLengthUpdated(uint256 epochLength);

    event WithdrawalDelayUpdated(uint64 withdrawalDelay);

    event RedeemRequest(
        address indexed controller,
        address indexed owner,
        uint256 indexed requestId,
        address sender,
        uint256 shares,
        uint256 assets
    );

    event Redeem(
        address indexed controller,
        address indexed receiver,
        uint256 indexed requestId,
        uint256 shares,
        uint256 assets,
        uint256 fee
    );

    event MinimumRedeemUpdated(uint256 minimumRedeem);

    event FeeVaultUpdated(address protocolFeeVault);

    event WithdrawalFeeUpdated(uint256 withdrawalFee);

    event RewardFeeUpdated(uint8 rewardFee);

    event ValidatorRebalance(uint64 validatorId, uint256 amount, bool isStaked);

    event RebalanceStarted(uint256 rebalanceInProgress);

    event ClaimedProtocolFees(uint256 rewardFees, uint256 withdrawalFees);

    error OnlyOracleOperatorAllowed();

    error TotalAssetsIsZero();

    error InvalidAmount();

    error InvalidRequestId();

    error InsufficientBalance();

    error UnauthorizedOperator();

    error AlreadyClaimed();

    error TransferFailed();

    error WaitMoreTime();

    error InvalidBlockNumber();

    error InvalidUtilisedPendingDeposit();

    error InvalidTotalStaked();

    error InvalidBurnableShares();

    error InvalidLastProcessedRequestId();

    error RequestIdsArrayFull();

    error BelowMinimumRedeemAmount();

    error InvalidWithdrawalFee();

    error InvalidRewardFee();

    error InvalidRange();

    error NoActiveValidators();

    error StakePrecompileDelegateFailed();

    error StakePrecompileUndelegateFailed();

    error StakePrecompileWithdrawFailed();

    error StakePrecompileClaimRewardsFailed();

    error ValidatorLengthMismatch();

    error RebalanceInProgressAlready();

    error RebalanceBatchNotWithdrawn();

    error TxAlreadyProcessed();

    error OutOfOrderOracleTx();

    error RebalanceNotSet();

    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _validatorsRegistry,
        address payable _stakePrecompile,
        address _feeVault,
        address _owner,
        uint256 _minimumRedeem,
        uint256 _withdrawalFee,
        uint8 _rewardFee,
        uint256 _epochLength,
        uint64 _withdrawalDelay
    ) public initializer {
        if (_withdrawalFee > MAX_BASIS_POINTS) revert InvalidWithdrawalFee();
        if (_rewardFee > MAX_PERCENTAGE) revert InvalidRewardFee();

        validatorsRegistry = _validatorsRegistry;
        stakePrecompile = _stakePrecompile;
        feeVault = _feeVault;
        nextRequestId = 1;
        minimumRedeem = _minimumRedeem;
        withdrawalFee = _withdrawalFee;
        rewardFee = _rewardFee;
        epochLength = _epochLength;
        withdrawalDelay = _withdrawalDelay;

        __ERC20_init("aPriori Monad LST", "aprMON");
        __Pausable_init();
        __Ownable_init(_owner);
        __ERC20Permit_init("aPriori Monad LST");
    }

    modifier onlyOracleOperator() {
        if (msg.sender != oracleOperator && msg.sender != owner()) revert OnlyOracleOperatorAllowed();
        _;
    }

    function asset() external pure returns (address assetTokenAddress) {
        return 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;
    }

    function updateOracleData(
        uint256 _blockNumber,
        uint256 _pendingDepositUtilisedForWithdrawals,
        uint256 _rewardsAfterProcessingWithdrawals,
        uint256 _totalStaked,
        uint256 _burnableShares,
        uint256 _lastProcessedRequestId,
        uint256 _rewardFees
    ) external onlyOracleOperator {
        _updateOracleData(
            _blockNumber,
            _pendingDepositUtilisedForWithdrawals,
            _rewardsAfterProcessingWithdrawals,
            _totalStaked,
            _burnableShares,
            _lastProcessedRequestId,
            _rewardFees
        );
    }

    function _updateOracleData(
        uint256 _blockNumber,
        uint256 _pendingDepositUtilisedForWithdrawals,
        uint256 _rewardsAfterProcessingWithdrawals,
        uint256 _totalStaked,
        uint256 _burnableShares,
        uint256 _lastProcessedRequestId,
        uint256 _rewardFees
    ) private {
        if (_blockNumber > block.number || _blockNumber <= lastProcessedBlockNumber) {
            revert InvalidBlockNumber();
        }
        if (_pendingDepositUtilisedForWithdrawals > totalPendingDeposit) revert InvalidUtilisedPendingDeposit();
        if (_totalStaked > totalStaked) revert InvalidTotalStaked();
        if (_lastProcessedRequestId == lastProcessedRequestId && _burnableShares > 0) revert InvalidBurnableShares();
        if (_lastProcessedRequestId >= nextRequestId) revert InvalidLastProcessedRequestId();

        lastProcessedBlockNumber = _blockNumber;
        totalPendingDeposit =
            totalPendingDeposit - _pendingDepositUtilisedForWithdrawals + _rewardsAfterProcessingWithdrawals;
        burnableShares = burnableShares + _burnableShares;
        totalStaked = _totalStaked;
        lastProcessedRequestId = _lastProcessedRequestId;
        rewardFeesAccumulated += _rewardFees;

        emit OracleDataUpdate(
            _blockNumber,
            totalPendingDeposit,
            totalStaked,
            burnableShares,
            _lastProcessedRequestId,
            rewardFeesAccumulated
        );
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function setOracleOperator(address _oracleOperator) external onlyOwner {
        oracleOperator = _oracleOperator;
        emit OracleOperatorUpdated(_oracleOperator);
    }

    function setWithdrawalFee(uint256 _withdrawalFee) external onlyOwner {
        if (_withdrawalFee > MAX_BASIS_POINTS) revert InvalidWithdrawalFee();

        withdrawalFee = _withdrawalFee;
        emit WithdrawalFeeUpdated(_withdrawalFee);
    }

    function setRewardFee(uint8 _rewardFee) external onlyOwner {
        if (_rewardFee > MAX_PERCENTAGE) revert InvalidRewardFee();

        rewardFee = _rewardFee;
        emit RewardFeeUpdated(_rewardFee);
    }

    function setValidatorsRegistry(address _validatorsRegistry) external onlyOwner {
        validatorsRegistry = _validatorsRegistry;
        emit ValidatorsRegistryUpdated(_validatorsRegistry);
    }

    function setStakePrecompile(address payable _stakePrecompile) external onlyOwner {
        stakePrecompile = _stakePrecompile;
        emit StakePrecompileUpdated(_stakePrecompile);
    }

    function setFeeVault(address _feeVault) external onlyOwner {
        feeVault = _feeVault;
        emit FeeVaultUpdated(_feeVault);
    }

    function setMinimumRedeem(uint256 _minimumRedeem) external onlyOwner {
        minimumRedeem = _minimumRedeem;
        emit MinimumRedeemUpdated(_minimumRedeem);
    }

    function setEpochLength(uint256 _epochLength) external onlyOwner {
        epochLength = _epochLength;
        emit EpochLengthUpdated(_epochLength);
    }

    function setWithdrawalDelay(uint64 _withdrawalDelay) external onlyOwner {
        withdrawalDelay = _withdrawalDelay;
        emit WithdrawalDelayUpdated(_withdrawalDelay);
    }

    function totalAssets() public view returns (uint256) {
        return totalPendingDeposit + totalStaked + rebalanceInProgress - midUpdateAdjustment - _calculateLockedRewards();
    }

    function convertToAssets(uint256 shares) public view returns (uint256 assets) {
        return _convertToAssets(shares, Math.Rounding.Floor);
    }

    function convertToShares(uint256 assets) public view returns (uint256 shares) {
        return _convertToShares(assets, Math.Rounding.Floor);
    }

    function maxDeposit(address receiver) external pure returns (uint256 maxAssets) {
        return type(uint256).max;
    }

    function previewDeposit(uint256 assets) external view returns (uint256 shares) {
        shares = convertToShares(assets);
    }

    function deposit(uint256 assets, address receiver) external payable whenNotPaused returns (uint256 shares) {
        if (assets <= DUST_THRESHOLD) revert InvalidAmount();
        if (assets != msg.value) revert InvalidAmount();

        shares = convertToShares(assets);

        if (shares == 0) revert InvalidAmount();

        totalPendingDeposit += assets;
        _mint(receiver, shares);

        emit Deposit(msg.sender, receiver, assets, shares);
    }

    function maxMint(address receiver) external pure returns (uint256 maxShares) {
        return type(uint256).max;
    }

    function previewMint(uint256 shares) external view returns (uint256 assets) {
        assets = _convertToAssets(shares, Math.Rounding.Ceil);
    }

    function mint(uint256 shares, address receiver) external payable whenNotPaused returns (uint256 assets) {
        assets = _convertToAssets(shares, Math.Rounding.Ceil);
        if (assets <= DUST_THRESHOLD || msg.value < assets) revert InvalidAmount();

        totalPendingDeposit += assets;
        _mint(receiver, shares);

        if (msg.value > assets) {
            (bool success,) = msg.sender.call{value: msg.value - assets}("");
            if (!success) revert TransferFailed();
        }

        emit Deposit(msg.sender, receiver, assets, shares);
    }

    function maxWithdraw(address owner) external view returns (uint256 maxAssets) {
        return convertToAssets(balanceOf(owner));
    }

    function previewWithdraw(uint256 assets) external view returns (uint256 shares) {
        shares = _convertToShares(assets, Math.Rounding.Ceil);
    }

    function maxRedeem(address owner) external view returns (uint256 maxShares) {
        return balanceOf(owner);
    }

    function previewRedeem(uint256 shares) external view returns (uint256 assets) {
        assets = convertToAssets(shares);
    }

    function setOperator(address operator, bool approved) external returns (bool) {
        isOperator[msg.sender][operator] = approved;
        emit OperatorSet(msg.sender, operator, approved);
        return true;
    }

    function requestRedeem(uint256 shares, address controller, address owner)
        external
        whenNotPaused
        returns (uint256 requestId)
    {
        if (shares == 0) revert InvalidAmount();
        if (balanceOf(owner) < shares) revert InsufficientBalance();
        if (owner != msg.sender && !isOperator[owner][msg.sender]) revert UnauthorizedOperator();

        requestId = nextRequestId;
        nextRequestId++;

        UserRequests storage _userRequests = userRequests[controller];
        uint256[] storage requestIds = _userRequests.requestIds;

        if (requestIds.length == 0) {
            requestIds.push(requestId);
            _userRequests.emptyHead = type(uint256).max;
        } else if (_userRequests.emptyHead == type(uint256).max) {
            if (requestIds.length > type(uint8).max) revert RequestIdsArrayFull();
            requestIds.push(requestId);
        } else {
            uint256 index = _userRequests.emptyHead;
            _userRequests.emptyHead = requestIds[index];
            requestIds[index] = requestId;
            isEmptyRequestSlot[controller][index] = false;
        }

        uint256 assets = convertToAssets(shares);
        if (assets < minimumRedeem) revert BelowMinimumRedeemAmount();

        redeemRequests[requestId] =
            RedeemData(shares, controller, assets, false, block.timestamp, currentWithdrawalBatchId);
        _transfer(owner, address(this), shares);

        emit RedeemRequest(controller, owner, requestId, msg.sender, shares, assets);
    }

    function getUserRequestDataCount(address user) external view returns (uint256 count) {
        (count,) = _getUserRequestData(user);
    }

    function getUserRequestData(address user, uint256 startIndex, uint256 pageSize)
        external
        view
        returns (RequestData[] memory requestData)
    {
        (uint256 count, uint256[] memory requestIds) = _getUserRequestData(user);

        if (count == 0) return requestData;

        uint256 endIndex = startIndex + pageSize;
        if (endIndex > requestIds.length) {
            endIndex = requestIds.length;
        }

        requestData = new RequestData[](endIndex - startIndex);
        uint256 currentIndex = 0;

        for (uint256 i = startIndex; i < endIndex; i++) {
            RedeemData storage redeemData = redeemRequests[requestIds[i]];
            requestData[currentIndex] = RequestData({
                id: requestIds[i],
                shares: redeemData.shares,
                assets: redeemData.assets,
                claimed: redeemData.claimed,
                claimable: redeemData.withdrawalBatchId <= lastProcessedWithdrawalBatchId,
                timestamp: redeemData.timestamp,
                unlockEpoch: withdrawalBatchUnlockEpochs[redeemData.withdrawalBatchId]
            });
            currentIndex++;
        }

        return requestData;
    }

    function viewRedeemRequest(uint256 requestId) external view returns (RequestData memory redeemRequest) {
        RedeemData storage redeemData = redeemRequests[requestId];
        redeemRequest = RequestData({
            id: requestId,
            shares: redeemData.shares,
            assets: redeemData.assets,
            claimed: redeemData.claimed,
            claimable: redeemData.withdrawalBatchId <= lastProcessedWithdrawalBatchId,
            timestamp: redeemData.timestamp,
            unlockEpoch: withdrawalBatchUnlockEpochs[redeemData.withdrawalBatchId]
        });
    }

    function claimableRedeemRequest(uint256 requestId, address controller) external view returns (uint256 shares) {
        RedeemData storage redeemRequest = redeemRequests[requestId];
        return redeemRequest.withdrawalBatchId <= lastProcessedWithdrawalBatchId && !redeemRequest.claimed
            ? redeemRequest.shares
            : 0;
    }

    function pendingRedeemRequest(uint256 requestId, address controller) external view returns (uint256 shares) {
        RedeemData storage redeemRequest = redeemRequests[requestId];
        return redeemRequest.withdrawalBatchId <= lastProcessedWithdrawalBatchId ? 0 : redeemRequest.shares;
    }

    function redeem(uint256[] calldata requestIDs, address receiver) external {
        for (uint256 i = 0; i < requestIDs.length;) {
            uint256 requestId = requestIDs[i];
            RedeemData storage redeemRequest = redeemRequests[requestId];
            if (redeemRequest.shares == 0) revert InvalidRequestId();
            if (redeemRequest.claimed) revert AlreadyClaimed();
            if (
                !paused()
                    && (redeemRequest.controller != msg.sender && !isOperator[redeemRequest.controller][msg.sender])
            ) {
                revert UnauthorizedOperator();
            }
            if (paused() && msg.sender != oracleOperator) revert OnlyOracleOperatorAllowed();

            if (redeemRequest.withdrawalBatchId > lastProcessedWithdrawalBatchId) {
                revert WaitMoreTime();
            }

            uint256 assets = redeemRequest.assets;
            _burn(address(this), redeemRequest.shares);
            burnableShares = burnableShares - redeemRequest.shares;
            redeemRequest.claimed = true;

            uint256 fee = (assets * withdrawalFee) / MAX_BASIS_POINTS;
            assets = assets - fee;

            UserRequests storage _userRequests = userRequests[redeemRequest.controller];
            uint256[] storage requestIds = _userRequests.requestIds;

            for (uint8 j = 0; j < requestIds.length;) {
                if (requestIds[j] == requestId && !isEmptyRequestSlot[redeemRequest.controller][j]) {
                    requestIds[j] = _userRequests.emptyHead;
                    _userRequests.emptyHead = j;
                    isEmptyRequestSlot[redeemRequest.controller][j] = true;
                    break;
                }
                unchecked {
                    ++j;
                }
            }

            (bool success,) = receiver.call{value: assets}("");
            if (!success) revert TransferFailed();

            withdrawalFeesAccumulated += fee;

            emit Redeem(redeemRequest.controller, receiver, requestId, redeemRequest.shares, assets, fee);

            unchecked {
                ++i;
            }
        }
    }

    function claimProtocolFees() external onlyOracleOperator {
        uint256 fees = rewardFeesAccumulated + withdrawalFeesAccumulated;

        emit ClaimedProtocolFees(rewardFeesAccumulated, withdrawalFeesAccumulated);

        rewardFeesAccumulated = 0;
        withdrawalFeesAccumulated = 0;

        (bool success,) = feeVault.call{value: fees}("");
        if (!success) revert TransferFailed();
    }

    function getPendingWithdrawalAmounts(uint256 batchSize)
        external
        view
        returns (
            uint256 _totalWithdrawalAmount,
            uint256 _totalBurnableShares,
            uint256 _nextRequestId,
            uint256 _pendingDeposit,
            uint256 _blockNumber
        )
    {
        uint256 toProcessRequestId = lastProcessedRequestId + batchSize;

        if (toProcessRequestId > nextRequestId - 1) {
            toProcessRequestId = nextRequestId - 1;
        }

        for (uint256 i = lastProcessedRequestId + 1; i <= toProcessRequestId; i++) {
            RedeemData storage redeemRequest = redeemRequests[i];
            if (redeemRequest.timestamp == 0) revert InvalidRange();

            _totalWithdrawalAmount += redeemRequest.assets;
            _totalBurnableShares += redeemRequest.shares;
        }

        _blockNumber = block.number;
        _nextRequestId = toProcessRequestId + 1;
        _pendingDeposit = totalPendingDeposit;
    }

    function _convertToAssets(uint256 shares, Math.Rounding rounding) internal view returns (uint256 assets) {
        uint256 redeemableShares = totalSupply() - burnableShares;
        if (redeemableShares == 0) return shares;
        return shares.mulDiv(totalAssets(), redeemableShares, rounding);
    }

    function _convertToShares(uint256 assets, Math.Rounding rounding) internal view returns (uint256 shares) {
        uint256 redeemableShares = totalSupply() - burnableShares;
        if (redeemableShares == 0) return assets;
        if (totalAssets() == 0) revert TotalAssetsIsZero();
        return assets.mulDiv(redeemableShares, totalAssets(), rounding);
    }

    function _calculateLockedRewards() internal view returns (uint256 lockedRewards) {
        uint256 elapsedBlocks = block.number - latestUpdateBlockNumber;

        if (elapsedBlocks >= epochLength || rewardsDistributing == 0) return 0;

        uint256 lockedRatio = 1e18 - elapsedBlocks.mulDiv(1e18, epochLength, Math.Rounding.Floor);

        return rewardsDistributing.mulDiv(lockedRatio, 1e18, Math.Rounding.Floor);
    }

    receive() external payable {}

    function claimValidatorRewards(
        uint256 start,
        uint256 limit,
        uint256 _totalWithdrawalAmount,
        uint256 _totalBurnableShares,
        uint256 _nextRequestId,
        uint256 _pendingDeposit,
        uint256 _blockNumber,
        bool _rebalanceNeeded
    ) external onlyOracleOperator {
        if (validatorBatchIndices.length == 0 && start != 0) {
            revert OutOfOrderOracleTx();
        } else if (validatorBatchIndices.length > 0 && start < validatorBatchIndices[validatorBatchIndices.length - 1])
        {
            revert OutOfOrderOracleTx();
        }
        if (oracleUpdateTracking[OracleTxType.CLAIM_REWARDS][start]) {
            revert TxAlreadyProcessed();
        }
        oracleUpdateTracking[OracleTxType.CLAIM_REWARDS][start] = true;
        validatorBatchIndices.push(start);

        if (start == 0) {
            oracleParams.totalWithdrawalAmount = _totalWithdrawalAmount;
            oracleParams.totalBurnableShares = _totalBurnableShares;
            oracleParams.nextRequestId = _nextRequestId;
            oracleParams.pendingDeposit = _pendingDeposit;
            oracleParams.blockNumber = _blockNumber;
            oracleParams.rebalanceNeeded = _rebalanceNeeded;
        }

        (ValidatorsRegistry.Validator[] memory validators, bool lastBatch) =
            ValidatorsRegistry(validatorsRegistry).getValidatorsBatch(start, limit);

        if (validators.length == 0) revert NoActiveValidators();

        (uint64 epoch,) = IStakePrecompile(stakePrecompile).getEpoch();

        (
            uint256[] memory stakePoolValidatorsStake,
            uint256 totalValidatorsStake,
            uint256 totalValidatorsScore,
            uint256 rewards
        ) = _fetchValidatorDataAndCollectRewards(validators);

