            ValidatorsRegistry.Validator[] memory validators,
            uint256[] memory stakePoolValidatorsStake,
            uint256 fee,
            uint256 netRewards,
            uint256 netWithdrawalAmount
        )
    {
        validators = validatorBatches[start];
        if (validators.length == 0) revert NoActiveValidators();

        stakePoolValidatorsStake = new uint256[](validators.length);
        for (uint256 i = 0; i < validators.length; i++) {
            stakePoolValidatorsStake[i] = validatorStakes[validators[i].id];
