        fee = (oracleData.totalRewards * rewardFee) / MAX_PERCENTAGE;
        netRewards = oracleData.totalRewards - fee;

        uint256 availableToWithdraw = oracleParams.pendingDeposit + netRewards;

        netWithdrawalAmount = oracleParams.totalWithdrawalAmount > availableToWithdraw
