    }

    function _getUserRequestData(address user) internal view returns (uint256 count, uint256[] memory requestIds) {
        UserRequests storage _userRequests = userRequests[user];
        uint256[] memory allRequestIds = _userRequests.requestIds;

        uint256 currentHead = _userRequests.emptyHead;
        uint256 emptyRequestCount = 0;
        uint256 tempIndex = 0;

        while (allRequestIds.length > 0 && currentHead != type(uint256).max) {
            emptyRequestCount++;

            tempIndex = currentHead;
            currentHead = allRequestIds[tempIndex];
            allRequestIds[tempIndex] = 0;
        }

        count = allRequestIds.length - emptyRequestCount;

        requestIds = new uint256[](count);
        uint256 currentIndex = 0;

        for (uint256 i = 0; i < allRequestIds.length; i++) {
            if (allRequestIds[i] != 0) {
                requestIds[currentIndex] = allRequestIds[i];
                currentIndex++;
            }
