// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

import {IStakePrecompile} from "./interfaces/IStakePrecompile.sol";

contract ValidatorsRegistry is OwnableUpgradeable {

    struct Validator {

        uint64 id;

        uint8 score;
    }

    mapping(address => bool) public managers;

    uint64[] public validatorIds;

    mapping(uint64 => Validator) public validators;

    IStakePrecompile public stakePrecompile;

    address public aprMON;

    uint64 public emptyHead;

    mapping(uint256 => bool) public isEmptySlot;

    event ManagerAdded(address manager);

    event ManagerRemoved(address manager);

    event ValidatorAdded(uint64 indexed id, uint8 score);

    event ValidatorScoreUpdated(uint64 id, uint8 score);

    event ValidatorRemoved(uint64 indexed id);

    error NotAuthorizedManager();

    error ValidatorAlreadyExists();

    error ValidatorNotRegistered();

    error LengthMismatch();

    error ValidatorNotFound();

    error InvalidLimit();

    error InvalidStartIndex();

    error ValidatorHasAssets();

    modifier onlyManager() {
        require(managers[msg.sender] || msg.sender == owner(), NotAuthorizedManager());
        _;
    }

    function initialize(address owner, address _stakePrecompile) public initializer {
        __Ownable_init(owner);
        stakePrecompile = IStakePrecompile(_stakePrecompile);
        emptyHead = type(uint64).max;
    }

    function setAprMON(address _aprMON) external onlyOwner {
        aprMON = _aprMON;
    }

    function addValidator(uint64 _id, uint8 _score) public onlyManager {
        require(validators[_id].id == 0, ValidatorAlreadyExists());
        (,,,,,,,,,, bytes memory secp_pubkey,) = stakePrecompile.getValidator(_id);
        require(secp_pubkey.length != 0, ValidatorNotRegistered());

        validators[_id] = Validator({id: _id, score: _score});

        if (emptyHead == type(uint64).max) {
            validatorIds.push(_id);
        } else {
            uint256 index = uint256(emptyHead);
            emptyHead = validatorIds[index];
            validatorIds[index] = _id;
            isEmptySlot[index] = false;
        }

        emit ValidatorAdded(_id, _score);
    }

    function addValidators(uint64[] calldata ids, uint8[] calldata scores) external onlyManager {
        require(ids.length == scores.length, LengthMismatch());
        for (uint256 i = 0; i < ids.length; i++) {
            addValidator(ids[i], scores[i]);
        }
    }

    function updateScores(uint64[] calldata id, uint8[] calldata score) external onlyManager {
        require(id.length == score.length, LengthMismatch());
        for (uint256 i = 0; i < id.length; i++) {
            require(validators[id[i]].id != 0, ValidatorNotFound());
            validators[id[i]].score = score[i];
            emit ValidatorScoreUpdated(id[i], score[i]);
        }
    }

    function removeValidator(uint64 _id) public onlyManager {
        require(validators[_id].id != 0, ValidatorNotFound());

        (uint256 stake,, uint256 rewards, uint256 delta_stake, uint256 next_delta_stake,,) =
            IStakePrecompile(stakePrecompile).getDelegator(_id, aprMON);

        if (validators[_id].score > 0 || stake > 0 || rewards > 0 || delta_stake > 0 || next_delta_stake > 0) {
            revert ValidatorHasAssets();
        }

        for (uint256 i = 0; i < validatorIds.length; i++) {
            if (validatorIds[i] == _id && !isEmptySlot[i]) {
                validatorIds[i] = emptyHead;
                emptyHead = uint64(i);
                isEmptySlot[i] = true;
                break;
            }
        }

        delete validators[_id];

        emit ValidatorRemoved(_id);
    }

    function removeValidators(uint64[] calldata ids) external onlyManager {
        for (uint256 i = 0; i < ids.length; i++) {
            removeValidator(ids[i]);
        }
    }

    function addManager(address manager) external onlyOwner {
        managers[manager] = true;
        emit ManagerAdded(manager);
    }

    function removeManager(address manager) external onlyOwner {
        managers[manager] = false;
        emit ManagerRemoved(manager);
    }

    function getNumValidators() public view returns (uint256) {
        uint256 count = 0;
        for (uint256 i = 0; i < validatorIds.length; i++) {
            if (!isEmptySlot[i]) {
                count++;
            }
        }
        return count;
    }

    function getValidators() external view returns (Validator[] memory) {
        uint256 count = getNumValidators();

        Validator[] memory validatorList = new Validator[](count);
        uint256 currentIndex = 0;

        for (uint256 i = 0; i < validatorIds.length; i++) {
            if (!isEmptySlot[i]) {
                validatorList[currentIndex] = validators[validatorIds[i]];
                currentIndex++;
            }
        }

        return validatorList;
    }

    function getValidatorsBatch(uint256 start, uint256 limit)
        external
        view
        returns (Validator[] memory, bool lastBatch)
    {
        require(limit > 0, InvalidLimit());

        uint256 totalCount = getNumValidators();

        require(start < totalCount, InvalidStartIndex());

        uint256 endIndex = start + limit;
        if (endIndex > totalCount) {
            endIndex = totalCount;
        }

        Validator[] memory validatorList = new Validator[](endIndex - start);
        uint256 currentIndex = 0;
        uint256 currentCount = 0;

        for (uint256 i = 0; i < validatorIds.length; i++) {
            if (!isEmptySlot[i]) {
                if (currentCount >= start && currentCount < endIndex) {
                    validatorList[currentIndex] = validators[validatorIds[i]];
                    currentIndex++;
                }
                currentCount++;
            }
        }

        return (validatorList, endIndex >= totalCount);
    }
}

